'use strict';
// The golden development package (audit P0-10): a real Download Complete Package ZIP generated by this Builder's own engine for
// a PBI 309446-shaped DAB + UI PBI (fixtures/pbi-309446-shape.cjs: six answered mandatory questions, CDMS and Legacy as read-only
// references, one attachment). Consumers such as the Akzo Master SDD agent test their import against it.
//   node make-golden-package.cjs     # rewrites fixtures/golden/pbi-309446-final-pbis.zip; run on every release
// test-570.cjs fails when a fresh package no longer has the golden one's file names, schemas or status values, or when the golden
// package is from another Builder version, so a rename reaches this fixture before it reaches a consumer.
const fs = require('node:fs/promises'), os = require('node:os'), path = require('node:path');
const P = require('./src/core.js'), F = require('./fixtures/pbi-309446-shape.cjs'), W = require('./fixtures/workspace.cjs'), { DirectoryHandle } = require('./fixtures/fs-handles.cjs');
const GOLDEN = path.join(__dirname, 'fixtures', 'golden', 'pbi-309446-final-pbis.zip');

// Returns {files, zip} for a freshly approved 309446-shaped PBI; the temporary workspace is removed.
async function goldenPackage() {
  const assets = JSON.parse(await fs.readFile(path.join(__dirname, 'src/assets.json'), 'utf8'));
  const tmp = await fs.mkdtemp(path.join(os.tmpdir(), 'akzo-golden-'));
  try {
    const o = { feature: 'Measurement', entity: 'measurement' }, dir = path.join(tmp, 'ws'), { files, config } = await F.build(P, fs, path, dir, o), root = new DirectoryHandle(dir);
    await P.apply(root, await P.plan(root, P.setupFiles(config, assets, '<html></html>').files, true), true); await P.discoverSources(root, config);
    const made = P.newPbi(config, { number: '309446', title: 'Measurement validation', description: 'Validate measurements before saving', acceptanceCriteria: '1. Given an invalid value, when it is saved, then the save is rejected with a clear message.', application: 'dab', legacy: 'legacy' });
    await P.apply(root, await P.plan(root, made.files));
    const folder = made.folder, state = await F.state(P, o, folder.split('/').pop(), files);
    await P.write(root, folder + '/pbi-state.json', JSON.stringify(state, null, 2)); await P.write(root, folder + '/DRAFT-PBI.md', W.draftDoc(state, state.status));
    await P.write(root, folder + '/DECISION-LOG.md', '# Decision log\n\nDEC-1 approved: stated in the original request.\n');
    await P.write(root, folder + '/attachments/measurement-rules.md', '# Measurement rules\nA measurement value must be positive.\n');
    for (const q of state.questions.filter(x => x.blocking)) await P.recordAnswer(root, folder, q.id, { option: 'A', by: 'Business analyst' });
    await P.synchronizePbi(root, folder);
    const review = await P.checkPbi(root, folder, true), approved = await P.approveAndGenerate(root, folder, 'Product owner', review.reviewedContent);
    const pkg = await P.developmentPackage(root, folder, approved.files);
    return { files: pkg, zip: new Uint8Array(await P.zip(pkg).arrayBuffer()) };
  } finally { await fs.rm(tmp, { recursive: true, force: true }); }
}
module.exports = { GOLDEN, goldenPackage };
if (require.main === module) (async () => {
  const { files, zip } = await goldenPackage();
  await fs.mkdir(path.dirname(GOLDEN), { recursive: true }); await fs.writeFile(GOLDEN, zip);
  console.log(`Wrote ${path.relative(__dirname, GOLDEN)}: ${Object.keys(files).length} files, ${zip.length} bytes (Builder ${P.VERSION}).`);
})().catch(e => { console.error(e); process.exitCode = 1; });
